// context/AuthContext.js - ВЕРСИЯ ДЛЯ РАБОТЫ С БАЗОЙ ДАННЫХ
import React, { createContext, useState, useContext, useEffect, useCallback } from 'react';
import { useModal } from './ModalContext';
import api from '../services/api';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const { showModal } = useModal();
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  // Нормализация товара
  const normalizeProduct = (product) => {
    if (product.images && Array.isArray(product.images) && product.images.length > 0) {
      return product;
    }
    if (product.image && typeof product.image === 'string') {
      return { ...product, images: [product.image] };
    }
    return { ...product, images: ['/images/placeholder.jpg'] };
  };

  // Загрузка данных пользователя с сервера
  const loadUserData = useCallback(async () => {
    if (!user || !token) return;
    try {
      const [cartRes, favRes, ordersRes] = await Promise.all([
        api.get('/cart'),
        api.get('/favorites'),
        api.get('/orders')
      ]);
      setCart(cartRes.cart || []);
      setFavorites(favRes.favorites || []);
      setOrders(ordersRes.orders || []);
    } catch (error) {
      console.error('Failed to load user data:', error);
    }
  }, [user, token]);

  // Восстановление сессии из localStorage (только токен и пользователь)
  useEffect(() => {
    const initializeAuth = async () => {
      setLoading(true);
      const savedToken = localStorage.getItem('auth_token');
      const savedUser = localStorage.getItem('auth_user');

      if (savedToken && savedUser) {
        try {
          // Валидируем токен на сервере
          const response = await api.get('/validate');
          if (response.valid && response.user) {
            setToken(savedToken);
            setUser(response.user);
            // Загружаем данные пользователя (корзина, избранное, заказы)
            const [cartRes, favRes, ordersRes] = await Promise.all([
              api.get('/cart'),
              api.get('/favorites'),
              api.get('/orders')
            ]);
            setCart(cartRes.cart || []);
            setFavorites(favRes.favorites || []);
            setOrders(ordersRes.orders || []);
          } else {
            // Токен невалидный — очищаем localStorage
            localStorage.removeItem('auth_token');
            localStorage.removeItem('auth_user');
          }
        } catch (error) {
          console.error('Token validation failed:', error);
          localStorage.removeItem('auth_token');
          localStorage.removeItem('auth_user');
        }
      }
      setLoading(false);
    };

    initializeAuth();
  }, []);

  // Регистрация через API
  const register = useCallback(async (userData) => {
    try {
      const response = await api.post('/register', {
        username: userData.username,
        email: userData.email,
        password: userData.password
      });

      const { token: authToken, user: newUser } = response;
      setToken(authToken);
      setUser(newUser);
      setCart([]);
      setFavorites([]);
      setOrders([]);

      localStorage.setItem('auth_token', authToken);
      localStorage.setItem('auth_user', JSON.stringify(newUser));

      return { user: newUser, token: authToken };
    } catch (error) {
      console.error('Registration error:', error);
      throw error;
    }
  }, []);

  // Вход через API
  const login = useCallback(async (email, password) => {
    try {
      const response = await api.post('/login', { email, password });
      const { token: authToken, user: loggedInUser } = response;

      setToken(authToken);
      setUser(loggedInUser);

      localStorage.setItem('auth_token', authToken);
      localStorage.setItem('auth_user', JSON.stringify(loggedInUser));

      // Загружаем данные пользователя
      const [cartRes, favRes, ordersRes] = await Promise.all([
        api.get('/cart'),
        api.get('/favorites'),
        api.get('/orders')
      ]);
      setCart(cartRes.cart || []);
      setFavorites(favRes.favorites || []);
      setOrders(ordersRes.orders || []);

      return { user: loggedInUser, token: authToken };
    } catch (error) {
      console.error('Login error:', error);
      throw error;
    }
  }, []);

  // Быстрый вход (создаёт тестового пользователя если нет)
  const quickLogin = useCallback(async () => {
    try {
      return await login('demo@luna-aurea.com', 'demo123');
    } catch (error) {
      if (error.message?.includes('Invalid credentials')) {
        await register({
          username: 'DemoUser',
          email: 'demo@luna-aurea.com',
          password: 'demo123'
        });
        return await login('demo@luna-aurea.com', 'demo123');
      }
      throw error;
    }
  }, [login, register]);

  // Выход
  const logout = useCallback(async () => {
    try {
      await api.post('/logout');
    } catch (error) {
      console.error('Logout error:', error);
    } finally {
      localStorage.removeItem('auth_token');
      localStorage.removeItem('auth_user');
      setToken(null);
      setUser(null);
      setCart([]);
      setFavorites([]);
      setOrders([]);
    }
  }, []);

  // Синхронизация корзины с сервером
  const syncCart = useCallback(async (newCart) => {
    if (user && token) {
      try {
        await api.put('/cart', { items: newCart });
      } catch (error) {
        console.error('Failed to sync cart:', error);
      }
    }
  }, [user, token]);

  // Синхронизация избранного с сервером
  const syncFavorites = useCallback(async (newFavorites) => {
    if (user && token) {
      try {
        await api.put('/favorites', { items: newFavorites });
      } catch (error) {
        console.error('Failed to sync favorites:', error);
      }
    }
  }, [user, token]);

  // Добавление в корзину
  const addToCart = useCallback((product) => {
    const normalizedProduct = normalizeProduct(product);
    const existingItem = cart.find(item => item.productId === normalizedProduct.id);
    let newCart;
    let message = '';

    if (existingItem) {
      newCart = cart.map(item =>
        item.productId === normalizedProduct.id
          ? { ...item, quantity: (item.quantity || 1) + 1 }
          : item
      );
      message = `Количество "${normalizedProduct.name}" увеличено!`;
    } else {
      newCart = [...cart, {
        productId: normalizedProduct.id,
        name: normalizedProduct.name,
        price: normalizedProduct.price,
        image: normalizedProduct.images?.[0] || normalizedProduct.image,
        quantity: 1
      }];
      message = `"${normalizedProduct.name}" добавлен в корзину!`;
    }

    setCart(newCart);
    syncCart(newCart);
    showModal('cart', normalizedProduct, message);
  }, [cart, syncCart, showModal]);

  // Удаление из корзины
  const removeFromCart = useCallback((productId) => {
    const newCart = cart.filter(item => item.productId !== productId);
    setCart(newCart);
    syncCart(newCart);
  }, [cart, syncCart]);

  // Добавление в избранное
  const addToFavorites = useCallback((product) => {
    const normalizedProduct = normalizeProduct(product);
    const isAlreadyFavorite = favorites.some(item => item.productId === normalizedProduct.id);

    if (!isAlreadyFavorite) {
      const newFavorites = [...favorites, {
        productId: normalizedProduct.id,
        name: normalizedProduct.name,
        price: normalizedProduct.price,
        image: normalizedProduct.images?.[0] || normalizedProduct.image
      }];
      setFavorites(newFavorites);
      syncFavorites(newFavorites);
      showModal('favorites', normalizedProduct, `"${normalizedProduct.name}" добавлен в избранное!`);
      return true;
    }
    return false;
  }, [favorites, syncFavorites, showModal]);

  // Удаление из избранного
  const removeFromFavorites = useCallback((productId) => {
    const newFavorites = favorites.filter(item => item.productId !== productId);
    setFavorites(newFavorites);
    syncFavorites(newFavorites);
  }, [favorites, syncFavorites]);

  const isInFavorites = useCallback((productId) => {
    return favorites.some(item => item.productId === productId);
  }, [favorites]);

  // Создание заказа
  const createOrder = useCallback(async (orderData) => {
    const newOrder = {
      orderId: Date.now().toString(),
      date: new Date().toLocaleString('ru-RU'),
      items: cart.map(item => ({
        productId: item.productId,
        name: item.name,
        price: item.price,
        image: item.image,
        quantity: item.quantity || 1
      })),
      total: cart.reduce((sum, item) => sum + (item.price * (item.quantity || 1)), 0),
      status: 'pending',
      address: orderData.address,
      cardNumberLast4: orderData.cardNumber.slice(-4)
    };

    if (user && token) {
      await api.post('/orders', { order: newOrder });
      // Перезагружаем данные пользователя
      const [cartRes, favRes, ordersRes] = await Promise.all([
        api.get('/cart'),
        api.get('/favorites'),
        api.get('/orders')
      ]);
      setCart(cartRes.cart || []);
      setFavorites(favRes.favorites || []);
      setOrders(ordersRes.orders || []);
    } else {
      // Если пользователь не авторизован, сохраняем локально
      const newOrders = [newOrder, ...orders];
      setOrders(newOrders);
      setCart([]);
    }

    return newOrder;
  }, [cart, orders, user, token]);

  // Отмена заказа
  const cancelOrder = useCallback(async (orderId) => {
    if (user && token) {
      await api.put(`/orders/${orderId}/cancel`);
      // Перезагружаем заказы
      const ordersRes = await api.get('/orders');
      setOrders(ordersRes.orders || []);
    } else {
      const newOrders = orders.map(order =>
        order.orderId === orderId ? { ...order, status: 'cancelled' } : order
      );
      setOrders(newOrders);
    }
  }, [orders, user, token]);

  const isAuthenticated = useCallback(() => {
    return !!user && !!token;
  }, [user, token]);

  const value = {
    user,
    token,
    cart,
    favorites,
    orders,
    loading,
    register,
    login,
    quickLogin,
    logout,
    isAuthenticated,
    addToCart,
    removeFromCart,
    addToFavorites,
    removeFromFavorites,
    isInFavorites,
    createOrder,
    cancelOrder
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
